// MineBench: choo-choo steam train — dramatic, unmistakable
// X-oriented train, center x~128, z~128. Y=0 ground, Y=1 rail top.
// Palette: white boiler, black cab/tender, red passenger, gold trim, green trees.

function wheel(cx,cy,cz,r,mat,hub){
  for(var b=-r;b<=r;b++)for(var a=-r;a<=r;a++){
    if(a*a+b*b>r*r+r)continue;
    if(r>=5&&a*a+b*b<(r-2)*(r-2)&&a!==0&&b!==0&&Math.abs(a)!==Math.abs(b))continue;
    block(cx,cy+b,cz+a,mat);
  }
  if(hub)block(cx-1,cy,cz,hub);
}
function elli(cx,cy,cz,rx,ry,rz,mat){
  for(var a=-rx;a<=rx;a++)for(var b=-ry;b<=ry;b++)for(var c=-rz;c<=rz;c++){
    if(a*a/(rx*rx)+b*b/(ry*ry)+c*c/(rz*rz)>1.0)continue;
    block(cx+a,cy+b,cz+c,mat);
  }
}

